create sequence battle_number_seq;
create table public.battle_queue(id uuid default gen_random_uuid() primary key,
user_id uuid not null,
fighter_name text not null,
genre text not null,
audio_path text,
original_file_name text not null,
status text default 'waiting'::text not null,
opponent_user_id uuid,
match_group_id uuid,
created_at timestamp with time zone default now() not null,
updated_at timestamp with time zone default now() not null,
ai_tool text,
lyrics text,
challenge_target_queue_id uuid,
search_deadline_at timestamp with time zone default (now() + '00:00:30'::interval) not null,
expires_at timestamp with time zone default (now() + '24:00:00'::interval) not null,
matched_at timestamp with time zone,
fallback_kind text,
public_vote_score integer,
cooldown_until timestamp with time zone,
scheduled_start_at timestamp with time zone,
cancellation_evaluation_at timestamp with time zone,
official_gatekeeper_id text,
official_gatekeeper_role text,
audio_sha256 text,
full_audio_path text,
full_audio_sha256 text,
full_audio_original_name text,
full_audio_duration_seconds numeric,
full_audio_public boolean default false not null,
drop_duration_seconds numeric,
song_stats_id uuid,
cover_url text,
full_song_youtube_url text,
source_type text default 'upload'::text not null,
source_url text,
title text,
creator text,
duration_seconds numeric,
rights_confirmed_at timestamp with time zone);
create table public.battles(id uuid default gen_random_uuid() primary key,
queue_a_id uuid not null,
queue_b_id uuid not null,
fighter_a_user_id uuid not null,
fighter_b_user_id uuid,
fighter_a_name text not null,
fighter_b_name text not null,
song_a_name text not null,
song_b_name text not null,
audio_a_path text,
audio_b_path text,
genre text not null,
status text default 'live'::text not null,
created_at timestamp with time zone default now() not null,
updated_at timestamp with time zone default now() not null,
ai_tool_a text,
ai_tool_b text,
winner text,
started_at timestamp with time zone default now(),
song_a_cover text,
lyrics_a text,
lyrics_b text,
battle_type text default 'formal'::text not null,
is_async_match boolean default false not null,
song_b_cover text,
stake_apc integer default 200 not null,
pot_apc integer default 400 not null,
vote_stake_apc integer default 50 not null,
waiting_room_started_at timestamp with time zone default now() not null,
battle_started_at timestamp with time zone,
battle_ended_at timestamp with time zone,
fighter_a_elo integer default 1200 not null,
fighter_b_elo integer default 1200 not null,
fighter_a_elo_delta integer default 0 not null,
fighter_b_elo_delta integer default 0 not null,
viewer_count_peak integer default 0 not null,
prediction_accuracy numeric default 0 not null,
battle_number bigint default nextval('battle_number_seq'::regclass),
result_archived_at timestamp with time zone,
cancellation_reason text,
scheduled_start_at timestamp with time zone,
cancellation_evaluation_at timestamp with time zone,
official_gatekeeper_id text,
fighter_a_avatar text,
fighter_b_avatar text,
q_crash_card_id uuid,
voting_ends_at timestamp with time zone,
winner_queue_id uuid,
song_stats_a_id uuid,
song_stats_b_id uuid);

